  Bu = `Натисніть кнопку праворуч, щоб надіслати свою сторінку на перевірку. Це слід зробити принаймні за 7 днів до бажаної дати публікації, щоб мати достатньо часу на перевірку та схвалення, а також на внесення необхідних змін.`,
  Vu = `Якщо до цієї сторінки буде потрібно внести будь-які зміни, команда Steam звернеться до вас через запит до служби підтримки Steamworks. Натисніть на кнопку праворуч, щоб переглянути запит і за потреби залишити коментар.`,
  Hu = `Якщо позначити сторінку затвердженою, партнер зможе опублікувати розпродаж і зробити його загальнодоступним`,
  Uu = `Надіслати запит на перевірку…`,
  Wu = `Надіслати запит на перевірку`,
  Gu = `Створює запит на перевірку та схвалення публікації сторінки розпродажу. Актуально, якщо на сторінці розпродажу вже представлені всі ігри, які ви плануєте показати, та остаточна версія ілюстрацій.`,
  Ku = `Буде створено запит до служби підтримки Steamworks на перевірку Valve вашої сторінки розпродажу. Цей запит слід надсилати лише тоді, коли версія зображень і тексту остаточна, а список ваших ігор більше не змінюватиметься.`,
  qu = `Переконайтеся, що вказали точну назву події та додали чіткий опис вгорі сторінки. Для подій-вітрин може знадобитися текстовий розділ угорі сторінки, у якому слід описати цю подію та умови її проведення.`,
  Ju = `Сторінка розпродажу буде заблокована після перевірки. Якщо вам потрібно внести зміни після перевірки або після початку події, залиште коментар з поясненнями, що це за зміни та чому вони не були внесені перед перевіркою.`,
  Yu = `Необов’язково: інформація для рецензентів`,
  Xu = `Оберіть партнерські акаунти, члени яких матимуть доступ до запиту`,
  Zu = `Необов’язково: надає іншим членам партнерських акаунтів доступ до запиту та можливість відповідати на нього. Стандартно права на читання й оновлення створеного запиту та відповідь на нього маєте лише ви.`,
  Qu = `Не вдалося створити запит. Спробуйте знову пізніше.`,
  $u = `Не можна створити новий запит — уже створений інший запит цього типу. Перш ніж надсилати нам цю сторінку розпродажу, слід завершити процес перевірки іншої або доповнити наявний запит інформацією про перевірку цієї сторінки.`,
  ed = `Запит успішно створено!`,
  td = `Відкрити запит на перевірку…`,
  nd = `Сторінку схвалено — тепер її можна опублікувати`,
  rd = `Перейдіть на вкладку «Публікація», щоб опублікувати сторінку.`,
  id = `Переконайтеся, що перевірили нижче налаштування видимості перед публікацією сторінки.`,
  ad = `Вам не видно цю гру через ваші <1>уподобання крамниці</1>.`,
  od = `Вам не видно цей пакунок через ваші <1>уподобання крамниці</1>.`,
