  HV = `Можливо, справа в захопливому ігроладі чи дивовижній історії з майстерно реалізованими персонажами, бездоганним дизайном чи запаморочливим багатокористувацьким режимом. Хай там як, переможниця номінації «Гра року 2020» приречена стати класикою.`,
  UV = `ВР-гра року — це не просто підміна звичної реальності. Ця гра вдосконалює реальність, використовуючи переваги ВР-середовища та розширюючи кордони віртуального світу.`,
  WV = `Ця гра вже не нова. Давно минули ті часи, коли автори показали світу своє творіння. Однак, вони виявилися дбайливими та працелюбними батьками, тож продовжують розвивати й підтримувати своє дитя. І навіть після стількох років, ця гра продовжує отримувати новий вміст.`,
  GV = `Є ігри, в яких щось не так, якщо грати наодинці. Можливо, вам потрібен друг, який би прикривав вас. Можливо, вам потрібен друг, якому ви б усадили ніж у спину. Хай там як, на тих, хто збирає друзів для таких ігор, очікують веселощі.`,
  KV = `Завданням візуального стилю не є точне відтворення реальності (хоч це й благородна мета)… Натомість він має наповнювати всю гру виразністю, яку можна відчути.`,
  qV = `Дизайнери цієї гри стоять на передовій креативної експериментальності та розширюють вашу уяву новою заворожливою взаємодією і паморочливими сюрпризами. Ця гра захоплювала, надихала й розважала з небаченою раніше новизною.`,
  JV = `Ця гра винагороджує наполегливість, вона не для слабкодухих. Це найскладніша гра, яка нам найбільше полюбилась.`,
  YV = `Цей неоспіваний герой заслуговує на визнання за його визначний музичний супровід. Це найоригінальніший саундтрек! `,
  XV = `Бувають часи, коли задовольнити може лише гра зі складним напруженим сюжетом. Хороші новини: це саме така гра. На неї можна підсісти, як на захопливий серіал, водночас вона гармонійна, як престижна кінострічка. Ця гра пробуджує почуття. Браво!`,
  ZV = `Ця гра — порятунок від напруженого дня. Спокійна, некваплива, вона змушує забути про будь-які тривоги. Ця гра — ваш момент абсолютної рівноваги.`,
  QV = `Змінити номінацію?`,
  $V = `Ви можете номінувати лише одну гру в кожній категорії, і для цієї ви вже номінували %1$s. Хочете натомість вибрати %2$s?`,
