  rH = `Переголосувати?`,
  iH = `Ви можете голосувати лише за одну гру в кожній категорії, і для цієї ви вже проголосували за %1$s. Хочете натомість проголосувати за %2$s?`,
  aH = `Схоже, ваш акаунт має обмеження. Щоб запобігти зловживанням, пов’язаним із номінуванням, ви маєте витратити в Steam 5 доларів США для участі в номінуванні на нагороди Steam. %1$s, щоб отримати докладнішу інформацію.`,
