  vH = `ВР-гра року — це не просто підміна звичної реальності. Ця гра вдосконалює реальність, використовуючи переваги ВР-середовища та розширюючи кордони віртуального світу.`,
  yH = `Ця гра вже не нова. Давно минули ті часи, коли автори показали світу своє творіння. Однак вони виявилися дбайливими та працелюбними батьками, тож продовжують розвивати й підтримувати своє дитя. І навіть після стількох років ця гра продовжує отримувати новий вміст.`,
  bH = `Є ігри, в яких щось не так, якщо грати наодинці. Можливо, вам потрібен друг, який би прикривав вас. Можливо, вам потрібен друг, якому ви б усадили ніж у спину. Хай там як, на тих, хто збирає друзів для таких ігор, очікують веселощі.`,
  xH = `Завданням візуального стилю не є точне відтворення реальності (хоч це й благородна мета)… Натомість він має надати грі неповторного вигляду і відчуття, з якими можна цілком і повністю поринути в неї.`,
  SH = `Дизайнери цієї гри стоять на передовій креативної експериментальності та розширюють вашу уяву новою заворожливою взаємодією і паморочливими сюрпризами. Ця гра захоплювала, надихала й розважала з небаченою раніше новизною.`,
