  zH = `ВР-гра року — це не просто підміна звичної реальності. Ця гра вдосконалює реальність, використовуючи переваги ВР-середовища та розширюючи кордони віртуального світу.`,
  BH = `Ця гра вже не нова. Давно минули ті часи, коли автори показали світу своє творіння. Однак вони виявилися дбайливими та працелюбними батьками, тож продовжують розвивати й підтримувати своє дитя. І навіть після стількох років ця гра продовжує отримувати новий вміст.`,
  VH = `Є ігри, в яких щось не так, якщо грати наодинці. Можливо, вам потрібен друг, який би прикривав вас. Можливо, вам потрібен друг, якому ви б усадили ніж у спину. Хай там як, на тих, хто збирає друзів для таких ігор, очікують веселощі.`,
  HH = `Завданням візуального стилю не є точне відтворення реальності (хоч це й благородна мета)… Натомість він має надати грі неповторного вигляду і відчуття, з якими можна цілком і повністю поринути в неї.`,
  UH = `Дизайнери цієї гри стоять на передовій креативної експериментальності та розширюють вашу уяву новою заворожливою взаємодією і паморочливими сюрпризами. Ця гра захоплювала, надихала й розважала з небаченою раніше новизною.`,
  WH = `Ця гра винагороджує наполегливість, вона не для слабкодухих. Це найскладніша гра, яка нам найбільше полюбилась.`,
  GH = `Цей неоспіваний герой заслуговує на визнання за його відмінний музичний супровід. Це найоригінальніший з найоригінальніших саундтреків! `,
  KH = `Бувають часи, коли задовольнити може лише гра зі складним напруженим сюжетом. Хороші новини: це саме така гра. На неї можна підсісти, як на захопливий серіал, водночас вона гармонійна, як престижна кінострічка. Ця гра пробуджує почуття. Браво!`,
  qH = `Ця гра — порятунок від напруженого дня. Спокійна, некваплива, змушує забути про усі тривоги. Ця гра — ваш момент абсолютної рівноваги.`,
  JH = `Ця гра настільки вам сподобалася, що її хотілось всюди брати з собою. І ви брали! На щастя, все, завдяки чому від неї неможливо було відірватись на комп’ютері, стало ще кращим на ходу.`,
  YH = `Лише з підтримкою ВР`,
  XH = `З підтримкою ВР`,
  ZH = `Залишилося %1$s до наступного розіграшу!`,
  QH = `Час до наступного розіграшу.`,
  $H = `Дивіться далі, щоб отримати шанс виграти!`,
  eU = `Триває розіграш`,
