  nU = `Роздача вже закінчилася. Дякуємо за участь.`,
  rU = `Роздача вже закінчилася, у нас є %1$s щасливих переможців. Дякуємо за участь.`,
  iU = `Клацніть тут, щоб дізнатися більше про призи, переможців та правила`,
