  OU = `Частина IV з IV`,
  kU = `Нефритовий Імператор закликав усіх істот своєї Імперії взяти участь у перегонах до небесного палацу, пообіцявши, що перші дванадцять будуть вшановані місцем у його новому календарі.

Кмітливий Щур був першим, хто перейшов річку до небесного царства. Він не був палким прихильником плавання, тому під’їхав на спині довірливого Бика і зіскочив у імператорський райський сад за мить до того, як пара дісталася берега.

Міцний Бик легко перейшов річку. Він не переймався результатами перегонів, а натомість відчував свою заслугу в успіхах Щура і щиро цьому радів.`,
  AU = `Самодостатній Тигр подорожував настільки обачно, що дозволив Бику обігнати себе (зрештою, краще дійти третім, ніж взагалі не дійти).

Спритний Кролик стрибнув на поліно, що плило собі поволі. Але хоч така стратегія виявилась не найкращою, удача була на його боці, адже попутний вітер стрімко прискорив саморобний човен.

Знаходячись високо в повітрі, летючий Дракон помітив, що жителі села в біді, — звісно, без жодних вагань він полетів на допомогу. Ця затримка дозволила Кролику раніше дістатися іншого берега річки завдяки утвореному пориву вітру, але для Дракона честь завжди важливіша за перемогу, тож п’яте місце його влаштувало.`,
  jU = `Потайлива Змія не дуже воліла самостійно вирушати в довгу дорогу: натомість вона вирішила непомітно оплестися навколо переднього копита Коня.

Коли Кінь майже добіг до фінішної лінії, Змія розмоталася й настільки налякала його, що встигла приповзти шостою, тоді як боязкий Кінь добіг наступним.`,
  MU = `Коза, Мавпа та Півень працювали разом, але Коза присвоїла собі восьме місце, бо була за головну в їхній групі. Наступною була весела Мавпа, а бундючний Півень прийшов десятим і пишався тим, що все було по-чесному.

Грайливий Пес був більше зацікавлений у брьоханні та плюсканні в воді, приймаючи одинадцяте місце в обмін на забави.

Останньою прийшла Свиня, яка зупинялася перекусити та передрімати. Вона була досить мудрою, щоб знати, що в Імператора знайдеться місце для кожної тварини.`,
  NU = `Зміни до профілю набудуть чинності після перевірки`,
